/* =====================================================================
 * 一、纯 JS MD5（UTF-8 友好，中文关键词必须走 UTF-8）
 * ===================================================================== */

function biliUtf8Bytes(str) {
  var out = [], i = 0, c, c2, cc;
  var s = String(str);
  while (i < s.length) {
    c = s.charCodeAt(i++);
