        'document.getElementById("curStv").textContent=t=="on"?"开启":"关闭";}' +
        '["reviewSwitch","sySwitch","progressSwitch","shelfSwitch","stvSwitch"].forEach(function(id){document.getElementById(id).addEventListener("change",sync);});' +
        'document.querySelectorAll("#styleSeg button").forEach(function(btn){btn.addEventListener("click",function(){' +
