function paraSettings() {
    let { java } = this;
    let conf = getConfig.call(this);
    let curReview = conf.para_review || 'off';
    let curStyle = conf.para_style || 'TEXT';
    let curSy = conf.para_sy || 'off';
    let curProgress = conf.progress_sync || 'off';
    let curShelf = conf.shelf_sync || 'off';

    var html = '<!DOCTYPE html><html lang="zh-CN"><head>' +
        '<meta charset="UTF-8">' +
