        '--radius-lg:20px;--radius:14px;' +
        '--shadow:0 18px 40px -26px rgba(31,45,80,.35),0 2px 8px rgba(31,45,80,.05);' +
        '--font-cn:"PingFang SC","Hiragino Sans GB","Microsoft YaHei",system-ui,-apple-system,sans-serif;' +
        '}' +
        '*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}' +
        'html,body{min-height:100%}' +
        'body{margin:0;min-height:100vh;color:var(--text);font-family:var(--font-cn);font-size:15px;line-height:1.6;' +
        'background:var(--bg);padding:calc(14px + env(safe-area-inset-top)) 14px calc(22px + env(safe-area-inset-bottom));position:relative;overflow-x:hidden}' +
        'body::before{content:"";position:fixed;inset:0;z-index:0;pointer-events:none;' +
        'background:radial-gradient(900px 520px at 12% -8%,rgba(var(--primary-rgb),.16),transparent 68%),' +
        'radial-gradient(760px 480px at 94% 4%,rgba(120,220,230,.18),transparent 72%)}' +
        '.wrap{max-width:720px;margin:0 auto;position:relative;z-index:1}' +
        '.glass{background:linear-gradient(155deg,rgba(var(--surface-rgb),.86),rgba(var(--surface-rgb),.58));' +
        'border:1px solid var(--border);border-radius:var(--radius-lg);box-shadow:var(--shadow);' +
        'backdrop-filter:blur(22px) saturate(1.2);-webkit-backdrop-filter:blur(22px) saturate(1.2)}' +
        '.hero{display:flex;align-items:center;gap:14px;padding:17px 18px;margin-bottom:12px}' +
        '.hero-icon{flex:0 0 auto;width:46px;height:46px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:20px;' +
        'background:linear-gradient(135deg,var(--primary),var(--primary-dark));color:#fff}' +
        '.hero h1{margin:0;font-size:19px;line-height:1.25}' +
        '.hero p{margin:5px 0 0;font-size:12px;line-height:1.55;color:var(--muted)}' +
        '.card{padding:16px 18px;margin-bottom:12px}' +
        '.group-title{font-size:12px;font-weight:700;color:var(--muted);letter-spacing:1px;padding:4px 2px 8px}' +
        '.row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0}' +
        '.row + .row{border-top:1px solid var(--border)}' +
        '.row .label{font-size:14px;font-weight:600}' +
        '.row .desc{font-size:11.5px;color:var(--muted);margin-top:2px;line-height:1.5}' +
        '.switch{position:relative;width:52px;height:28px;flex:none;cursor:pointer}' +
        '.switch input{opacity:0;width:0;height:0}' +
        '.switch-slider{position:absolute;inset:0;background:rgba(var(--line-rgb),.35);border-radius:28px;transition:.3s;border:1px solid var(--border)}' +
        '.switch-slider::before{content:"";position:absolute;width:22px;height:22px;left:2px;bottom:2px;background:#fff;border-radius:50%;transition:.3s;box-shadow:0 2px 8px rgba(0,0,0,.3)}' +
