        // 段评
        '<section class="card glass">' +
        '<div class="group-title">段评</div>' +
        '<div class="row"><div><div class="label">段评开关</div><div class="desc">仅番茄、企鹅阅读、晋江、七猫、少年梦、起点支持</div></div>' +
