function esc(s) {
    s = (s == null) ? '' : String(s);
    return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function getTheme() {
    var h = [12, 28, 152, 168, 188, 205, 222, 248, 332][Math.floor(Math.random() * 9)];
    var s = 44 + Math.floor(Math.random() * 14);
    var l = 34 + Math.floor(Math.random() * 8);
    return `hsl(${h} ${s + 4}% ${l}%)`;
}

// 基础数据
var p = html.match(/([\d,]+)\s*张照片/);
var v = html.match(/([\d,]+)\s*次浏览/);
var d = html.match(/(\d{4}年\d{1,2}月\d{1,2}日)/);

var photos = p ? p[1] : "-";
var views = v ? v[1] : "-";
var date = d ? d[1] : "-";

var model = java.getString("div.mb-4 > a[href*='/models/']@text") || "-";
var series = java.getString("div.mb-4 > a[href*='/series/']@text") || "-";
var category = java.getString("div.mb-4 > a[href*='/categories/']@text") || "-";

// 简介
var intro = java.getString("meta[name=description]@content") || java.getString("p.text-secondary.text-sm.leading-relaxed@text") || "暂无简介";
intro = esc(intro.trim());

//  Tag
var tagsHtml = "";
var i = 0;
var colors = [
    { bg: '#ecf5ff', bc: '#d9ecff', tc: '#409eff' },
    { bg: '#f0f9eb', bc: '#e1f3d8', tc: '#67c23a' },
    { bg: '#fdf6ec', bc: '#faecd8', tc: '#e6a23c' },
    { bg: '#fef0f0', bc: '#fde2e2', tc: '#f56c6c' },
    { bg: '#f4f4f5', bc: '#e9e9eb', tc: '#909399' }
];

var reg = /<a[^>]+href="([^"]*\/tags\/[^"]*)"[^>]*>\s*(#[^<]+?)\s*<\/a>/gi;
var m;
while ((m = reg.exec(html)) !== null) {
    var u = String(m[1]).split("'").join("\\'");
    var t = m[2].trim();

    if (t && u) {
        var name = String(t).substring(1);
        var nameEsc = name.split("'").join("\\'");
        var c = colors[i % colors.length];


        var uPage = u + "?page=1";
        var action = encodeURIComponent(`java.open('explore', '${uPage}', '标签: ${nameEsc}');`);

        tagsHtml += `<a href="javascript:${action}" style="text-decoration:none; display:inline-flex; align-items:center; background:${c.bg}; border:1px solid ${c.bc}; color:${c.tc}; height:24px; padding:0 9px; border-radius:4px; font-size:12px; margin:0 6px 8px 0; white-space:nowrap; font-weight:500;">${t}</a>`;
        i++;
    }
}

// 推荐
var recHtml = "";
var recReg = /<a\s+href="([^"]+\/albums\/[^"]+)"\s+class="album-card[^>]*>[\s\S]*?<img\s+src="([^"]+)"[\s\S]*?<h3[^>]*>([^<]+)<\/h3>/gi;
var r;
var rc = 0;
var safeSourceUrl = String(source.bookSourceUrl || "").split("'").join("\\'");

while ((r = recReg.exec(html)) !== null && rc < 8) { 
    var rImg = r[2];
    var rawTitle = String(r[3]).trim();


    var cleanTitle = rawTitle.replace(/\s*[（(][^）)]*[）)]/g, "").trim();
    var safeKeyword = cleanTitle.split("'").join("\\'");

    var rAction = encodeURIComponent(`java.open('search', '${safeKeyword}', '${safeKeyword}', '${safeSourceUrl}');`);

    recHtml += `
    <a href="javascript:${rAction}" class="rec-card">
        <div class="img-box">
            <img src="${rImg}" onerror="this.style.display='none'">
        </div>
        <div class="rec-title">${rawTitle}</div>
        <div class="rec-tip">🔍 源内搜索</div>
    </a>`;
    rc++;
}

var accent = getTheme();

var htmlCode = `
<useweb>
<style>
:root { --ink: #1c1917; --mute: #78716c; --line: #e7e5e4; --paper: #fafaf9; --accent: ${accent}; --font: "Segoe UI", "PingFang SC", system-ui, sans-serif; }
