    h = u8(raw.slice(0, e));
}
if (h.length < 20) {
    var q = s.match(/<div id="booktxthtml">([\s\S]*?)<\/div>/);
    h = q ? q[1] : "";
}
h = h.split(String.fromCharCode(0)).join("").replace(/<script[\s\S]*?<\/script>/gi, "").replace(/<br\s*\/?>/gi, "\n").replace(/<\/p>/gi, "\n").replace(/<\/div>/gi, "\n").replace(/<[^>]+>/g, "");
h = h.split("\r").join("").split("&nbsp;").join(" ").split("&lt;").join("<").split("&gt;").join(">").split("&quot;").join("\"").split("&#39;").join("'").split("&amp;").join("&");
