//        ② 传不进来的（服务器下发的点击串）用 _DP_JV/_DP_BK/_DP_CH 兜底。
var _DP_JV = null, _DP_BK = null, _DP_CH = null;
var _DP_ILLU_DIAG = '';   // ★ v54 插图链路诊断串
function _dpSetCtx(jv, bk, ch) {
    try { if (jv) _DP_JV = jv; } catch (e1) {}
    try { if (bk) _DP_BK = bk; } catch (e2) {}
    try { if (ch) _DP_CH = ch; } catch (e3) {}
    return _DP_JV;
}
// ★ 2026-09-30：安全取规则作用域的 chapter。
//   旧写法在 jsLib 内部直接写 `chapter || null` —— 一旦当前作用域没有 chapter
//   绑定（详情/搜索规则、或引擎换 ctx 后），会抛 ReferenceError。
//   这条链在 __dpThirdParty / _dpBookIntro 里，被 try 吞掉 → 表现为
//   「VIP 补章静默返回空」「简介恒空」，极难定位。改为 typeof 守卫。
function _dpScopeChapter() {
    try { if (typeof chapter !== 'undefined' && chapter) return chapter; } catch (e1) {}
    try { if (_DP_CH) return _DP_CH; } catch (e2) {}
    return null;
}
// 取 java：显式传的 > 兜底缓存 > 作用域全局（后者一般取不到，留着兼容老上下文）
function _dpJv(jv) {
