//   ★ 注意：「能否解出正文」**不是**凭证判据 —— 番茄 v1 密钥是按 **device_id** 注册的，
//     与账号无关；免费章任何人（含完全匿名）都能解出同样的正文（实测 20365 字 / free_para_nums=204）。
//     所以客户端只要把 Cookie 送上去，由服务端验号即可。
var _DP_FQ_GRAB_CHAN = '';

function _dpFqCookieGet(jv, tag, ckObj) {
    var v = '';
    try {
        if (ckObj && typeof ckObj.getCookie === 'function') v = String(ckObj.getCookie(tag) || '');
    } catch (e0) { v = ''; }
    if (!v) {
        try {
            if (typeof cookie !== 'undefined' && cookie && typeof cookie.getCookie === 'function') {
                v = String(cookie.getCookie(tag) || '');
            }
        } catch (e1) { v = ''; }
    }
    if (!v && jv) {
        try { if (typeof jv.getCookie === 'function') v = String(jv.getCookie(tag) || ''); } catch (e2) { v = ''; }
    }
    if (!v && jv) {
        try {
            if (typeof jv.getCookieStore === 'function') {
                var st = jv.getCookieStore();
                if (st && typeof st.getCookie === 'function') v = String(st.getCookie('https://' + tag + '/') || '');
            }
