    return v;
}

// 抓番茄各域名的 Cookie 并合并（v57：cookie/java.getCookie + 域名 tag）
// 优先 fanqienovel.com（社区源也是只读这个域）；拿不到再退回 snssdk/字节系。
// 本地预筛：没看到任何登录态 cookie 名就直接返回 ''（省一次上传；真正判真假由服务端验号）。
//   install_id / ttreq 匿名也有，不能当登录判据。
function _dpFqGrabCookie(jav, ckObj) {
    var jv = _dpJv(jav);
    var PREF = ['fanqienovel.com', 'www.fanqienovel.com', 'm.fanqienovel.com'];
    var REST = ['fqnovel.com', 'reading.snssdk.com', 'snssdk.com', 'bytedance.com'];
    var chan = [];
    var SESS = /(?:^|;\s*)(?:sessionid|sessionid_ss|sid_guard|sid_tt|sid_ucp_v1|ssid_ucp_v1)=/;

    function merge(list) {
        var bag = {}, order = [], i, j, m;
        for (i = 0; i < list.length; i++) {
            var c = _dpFqCookieGet(jv, list[i], ckObj);
            if (!c) continue;
            chan.push(list[i] + '(' + c.length + ')');
            var parts = c.split(';');
            for (j = 0; j < parts.length; j++) {
                var kv = String(parts[j]).replace(/^\s+|\s+$/g, '');
                if (!kv || kv.indexOf('=') < 0) continue;
                var k = kv.split('=')[0];
                if (k && !bag[k]) { bag[k] = kv; order.push(k); }
            }
        }
        var out = [];
        for (m = 0; m < order.length; m++) out.push(bag[order[m]]);
        return out.join('; ');
    }

    var s1 = merge(PREF);
    if (SESS.test(s1)) {
        try { _DP_FQ_GRAB_CHAN = chan.join(', '); } catch (eA) {}
        return s1;
    }
    var s2 = merge(REST);
    var all = (s1 && s2) ? (s1 + '; ' + s2) : (s1 || s2);
    try { _DP_FQ_GRAB_CHAN = chan.join(', ') || '(空)'; } catch (eB) {}
    return SESS.test(all) ? all : '';
}

// 抓本机 Cookie → 上传服务器自动保存
// （只送 Cookie；X-Tt-Token 服务端实测不需要，缺了就沿用上次的值）
//
// ★ 上传走三条策略，按「最不依赖 Rhino 类型转换」的顺序试：
//   S1 GET  /fq/auth/setq?ck=<encodeURIComponent(ck)>
//        —— java.ajax(url) 只吃 URL，不碰 headers Map，最稳（书源 _dp3Try 也拿它当兜底）
//   S2 POST /fq/auth/set  body=JSON, headers={...}
//        —— Legado 的 post 签名是 headers: Map<String,String>，实现体直接 headers.toMutableMap()，
//           **不做 JSON 解析**；JS 对象字面量能否被 Rhino 转成 Map 不确定，故只作兜底
//   S3 POST /fq/auth/set  body=JSON, headers={}   —— 空对象，转换失败概率更低
function _dpFqGrabSave(jav, ckObj) {
    try {
        var jv = _dpJv(jav);
        var ck = _dpFqGrabCookie(jv, ckObj);
        if (!ck) {
            try { jv.toast('❌ 没抓到登录态 Cookie —— 已打开诊断页'); } catch (e0) {}
            try { _dpFqDiag(jv); } catch (eD) {}
            return '';
        }
        var base = _dpFqAuthBase(jv);
        var txt = '', how = '';
        var tries = [];

        // S1：GET + encodeURIComponent
        try {
            var enc = '';
            try { enc = encodeURIComponent(ck); } catch (eE) { enc = ck; }
            var u = base + '/fq/auth/setq?ck=' + enc;
            txt = String(jv.ajax(u, 20000) || '');
            how = 'S1 GET /fq/auth/setq';
        } catch (e1) { txt = ''; tries.push('S1:' + (e1 && e1.message ? e1.message : e1)); }

        // S2：POST，headers 传 JS 对象
        if (!txt) {
            try {
                var p2 = JSON.stringify({ Cookie: ck });
                txt = String(jv.post(base + '/fq/auth/set', p2,
                    { 'Content-Type': 'application/json;charset=utf-8' }, 20000).body() || '');
                how = 'S2 POST /fq/auth/set';
            } catch (e2) { txt = ''; tries.push('S2:' + (e2 && e2.message ? e2.message : e2)); }
        }

        // S3：POST，headers 传空对象
        if (!txt) {
            try {
                var p3 = JSON.stringify({ Cookie: ck });
                txt = String(jv.post(base + '/fq/auth/set', p3, {}, 20000).body() || '');
                how = 'S3 POST(空headers)';
            } catch (e3) { txt = ''; tries.push('S3:' + (e3 && e3.message ? e3.message : e3)); }
        }

        var ok = false, msg = '', tail = '';
        try {
            var o = JSON.parse(txt);
            ok = !!o.ok;
            if (ok) {
                msg = o.user || o.probe || '';
                var stt = o.status || {};
                var dl = (stt.days_left === null || stt.days_left === undefined) ? null : stt.days_left;
                if (dl !== null) tail = '（剩 ' + dl + ' 天）';
            } else {
                msg = o.err || '';
            }
        } catch (e4) {}
        try { jv.toast(ok ? ('✅ 番茄凭证已保存 · ' + msg + tail) : ('❌ 保存失败：' + (msg || '服务器无响应'))); } catch (e5) {}
        if (ok) {
            try { if (jv.refreshContent) jv.refreshContent(); } catch (e7) {}
        } else {
            try {
                var d = _dpFqDiagText(jv);
                d += '\n\n--- 本次上传 ---\n抓取通道: ' + String(_DP_FQ_GRAB_CHAN || '(无)')
                   + '\nCookie 长度: ' + ck.length
                   + '\n上传策略: ' + (how || '(三条全失败)')
                   + '\n策略报错: ' + (tries.join(' | ') || '(无)')
                   + '\n服务器返回: ' + (txt || '(空)');
                _dpFqShowDiag(jv, '❌ 保存失败 · 诊断', d);
            } catch (e8) {}
        }
    } catch (e) { try { jav.toast('抓取失败：' + (e && e.message ? e.message : e)); } catch (e9) {} }
    return '';
}

