        // 类型归一：畸形 changelog（字符串/数字/null）不允许抛 TypeError ——
        // 外层 catch 会把 JS 异常当报错文案弹给用户，且不唤起更新（2026-10-23 深度测试 S2）。
        var ch = [];
        if (Object.prototype.toString.call(remote.changes) === '[object Array]') { ch = remote.changes; }
        var shown = ch.slice(0, 5);
        if (shown.length) { msg += '\n' + shown.join('\n'); }
        if (ch.length > 5) { msg += '\n…共 ' + ch.length + ' 条，详情可看更新日志页'; }
        var notice = '';
        try { if (remote.notice != null) { notice = String(remote.notice); } } catch (eN) {}
