function _aqLimitSrcText(q) {
    var s = String((q && q.source) || '');
    if (s === 'exempt') return '豁免·不限';
    if (s === 'custom') return '单独设的额度';
    if (s === 'default') return '默认额度';
    return '来源未知';
}

// st 可选：调用方已经取过 /user/auth/status 就传进来，省一次网络请求。
function _aqQuotaText(st) {
