function _dpLuRow(name, label, action, dynLabel, basis) {
    var r = {
        name: name, type: 'button',
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: (basis == null ? 0.45 : basis)
        }
    };
    // ★ 2026-10-20：dynLabel=false 时用 JSON.stringify 生成 JS 字符串字面量。
    //   旧写法 "'" + label + "'" 遇到 label 里的反斜杠会转义掉收尾引号 →
    //   Legado eval viewName 时 SyntaxError → _dpAqUi 的 catch 返回 '[]' → 登录页空白。
    //   label 可能来自服务端 codeHint（管理员可改），属于可控输入，必须转义。
    r.viewName = dynLabel ? String(label) : JSON.stringify(String(label));
    if (action) r.action = action;
    return r;
}

