function shortenNumber(number, digits) {
    digits = digits !== undefined ? digits : 2;
    const suffixes = ['', 'K', 'M', 'B', 'T'];
    let suffixIndex = 0;
    while (number >= 1000) {
        number /= 1000;
        suffixIndex++;
