@js:
var sort = [],
h = java.ajax("http://www.ibooktxt.net/rank"),
j = org.jsoup.Jsoup.parse(h),
rankLinks = j.select(".rank h2 a"),
navLinks = j.select(".nav ul li a");

// 添加排行榜分类
sort = Array.from(rankLinks, (a, i) => ({
    "title": a.text(),
    "url": "http://www.ibooktxt.net" + a.attr("href"),
    "style": {
      "layout_flexGrow": 1,
      "layout_flexBasisPercent": 0.25
    }
}));

var navArray = [];
for (var i = 0; i < navLinks.size(); i++) {
    navArray.push(navLinks.get(i));
}

// 添加小说分类（从第4个开始，跳过首页、排行、书库）
var categoryLinks = navArray.slice(3, 12); // 取玄幻到其他分类（第3到第10个）
categoryLinks.forEach((a, i) => {
    sort.push({
        "title": a.text(),
        "url": "http://www.ibooktxt.net" + a.attr("href").replaceAll(/\/\d+\//, "/{{page}}/"),
        "style": {
            "layout_flexGrow": 1,
            "layout_flexBasisPercent": 0.25
        }
    });
});

JSON.stringify(sort);

