i=0;
while(i<list.length){
if(i==0){
sb+=list[i]
}else{
    if(list[i].match(/lang-app=/)){  
      i2=i+1;
     i3=i2+1;
     if (list[i2] != null && list[i2].match(/lang=/)) {
                        sb+="&";
                        sb+=list[i2];

                        sb+="&";
                        sb+=list[i];

                        i = i3;
                    }
