ruleToc.chapterList:
@js:
var res = JSON.parse(java.get('res'));
var html = res.zjstr;
// 定义正则表达式匹配章节名称和链接
var regex = /<a href="(.*?)" title="(.*?)".*?>(.*?)<\/a>/g;

// 存储提取结果的数组
var chapters = [];

// 循环匹配所有符合条件的结果
var match;
while ((match = regex.exec(html)) !== null) {
  var href = match[1]; // 链接
  var title = match[2]; // 章节名称

  // 将结果存入数组
  chapters.push({
    text: title,
    href: href
  });
}
chapters;

