var regex = /<li ?[^>]*><a ?[^>]* ?href="([^"]*\/sort\/\d+_[\d\w\.]+\/?)">([^<]+)<\/a>(<(span|i)>共有? ?(\d+) ?本<\/(span|i)>)?<\/li>/g;
const html = res.body();

const categories = [{
  title: "分类",
  style: {
    "layout_flexBasisPercent": 1,
    "layout_flexGrow": 1
  }
}];

let match;
while ((match = regex.exec(html)) != null) {
  categories.push({
    url: match[1],
    title: match[2],
    count: parseInt(match[5], 10),
    style: {
      "layout_flexBasisPercent": 0.25,
      "layout_flexGrow": 1
    }
  });
}

JSON.stringify(categories);

